CREATE TABLE "refresh_tokens" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" BIGINT NOT NULL,
    "token" TEXT NOT NULL,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "ip" TEXT,
    "user_agent" TEXT,
    PRIMARY KEY ("id")
);
CREATE INDEX "index_refresh_tokens_by_user_id" ON "refresh_tokens" ("user_id");
CREATE UNIQUE INDEX "index_refresh_tokens_by_token" ON "refresh_tokens" ("token");
CREATE TABLE "files" (
    "id" UUID NOT NULL,
    "user_id" BIGINT NOT NULL,
    "original_name" TEXT NOT NULL,
    "mime_type" TEXT NOT NULL,
    "file_size" BIGINT NOT NULL,
    "width" BIGINT,
    "height" BIGINT,
    "hash" TEXT NOT NULL,
    "state" TEXT NOT NULL,
    "attached_at" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX "index_files_by_user_id" ON "files" ("user_id");
-- 生成器不认识 CHECK：重生成这份基础迁移后必须手工补回。
ALTER TABLE "files" ADD CONSTRAINT "files_state_attached_at_consistent" CHECK ((state = 'draft') = (attached_at IS NULL));
CREATE TABLE "users" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "username" TEXT NOT NULL,
    "password" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "index_users_by_username" ON "users" ("username");
CREATE TABLE "user_roles" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" BIGINT NOT NULL,
    "role_id" BIGINT NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "index_user_roles_by_user_id_and_role_id" ON "user_roles" ("user_id", "role_id");
CREATE INDEX "index_user_roles_by_user_id" ON "user_roles" ("user_id");
CREATE INDEX "index_user_roles_by_role_id" ON "user_roles" ("role_id");
CREATE TABLE "roles" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" TEXT NOT NULL,
    "description" TEXT,
    "permissions" JSONB NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "index_roles_by_name" ON "roles" ("name");
CREATE TABLE "sessions" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" BIGINT NOT NULL,
    "token" TEXT NOT NULL,
    "expires_at" TIMESTAMPTZ(6) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "ip" TEXT,
    "user_agent" TEXT,
    PRIMARY KEY ("id")
);
CREATE INDEX "index_sessions_by_user_id" ON "sessions" ("user_id");
CREATE UNIQUE INDEX "index_sessions_by_token" ON "sessions" ("token");
